package com.shortner.agent.orchestration.entity;
import com.shortner.agent.orchestration.model.RunStatus; import jakarta.persistence.*; import java.time.*;
@Entity public class WorkflowRun { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String scenario; @Column(nullable=false,length=4000) private String requirement; @Enumerated(EnumType.STRING) @Column(nullable=false) private RunStatus status=RunStatus.PENDING; @Column(nullable=false) private Instant startedAt=Instant.now(); private Instant finishedAt; @Column(length=1000) private String stopReason; protected WorkflowRun(){} public WorkflowRun(String scenario,String requirement){this.scenario=scenario;this.requirement=requirement;} public Long getId(){return id;} public String getScenario(){return scenario;} public String getRequirement(){return requirement;} public RunStatus getStatus(){return status;} public Instant getStartedAt(){return startedAt;} public Instant getFinishedAt(){return finishedAt;} public String getStopReason(){return stopReason;} public void status(RunStatus value){status=value;} public void finish(){finishedAt=Instant.now();} public void stop(String reason){stopReason=reason;status=RunStatus.SAFE_STOPPED;finish();} }
